// Adapted from shadcn/ui (MIT). See SHADCN-LICENSE.txt and upstream provenance.
"use client";

import * as React from "react";
import { cn } from "./utils";
import { CheckIcon } from "lucide-react";
import { Checkbox as CheckboxPrimitive } from "radix-ui";

function Checkbox({
  className,
  ...props
}: React.ComponentProps<typeof CheckboxPrimitive.Root>) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      className={cn("roc-ui", className)}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        data-slot="checkbox-indicator"
        className="roc-ui"
      >
        <CheckIcon className="roc-ui-icon" />
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  );
}

export { Checkbox };

import "./checkbox.css";

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

@import "./ui-base.css";
.roc-ui[data-slot="checkbox"] {
  display: inline-grid;
  place-items: center;
  position: relative;
  width: 20px;
  height: 20px;
  padding: 0;
  flex-shrink: 0;
  border: 1px solid var(--roc-line, #c7c7c7);
  border-radius: 5px;
  background: var(--roc-paper, #fff);
  cursor: pointer;
}
.roc-ui[data-slot="checkbox"]::before {
  content: "";
  position: absolute;
  inset: -8px;
}
.roc-ui[data-slot="checkbox"][data-state="checked"],
.roc-ui[data-slot="checkbox"][data-state="indeterminate"] {
  background: var(--roc-ink, #252525);
  border-color: transparent;
  color: white;
}
.roc-ui[data-slot="checkbox-indicator"] {
  display: grid;
  place-items: center;
  color: inherit;
}
.roc-ui[data-slot="checkbox"][data-state="indeterminate"] svg {
  visibility: hidden;
}
.roc-ui[data-slot="checkbox"][data-state="indeterminate"]::after {
  content: "";
  position: absolute;
  width: 10px;
  height: 2px;
  background: currentColor;
}

/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-size: 13px;
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible {
  outline: 2px solid var(--roc-focus, #737373);
  outline-offset: 3px;
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
@keyframes roc-ui-reveal {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}
